
% Homework 4 Problem 6

% Part (a)

% Read image
f = imread('HW4Q6_original_image.jpg');

% Convert to grayscale
if ndims(f) == 3
    f = 0.2989*f(:,:,1) + 0.5870*f(:,:,2) + 0.1140*f(:,:,3);
end

% Convert to double
f = double(f);

% Get image size
[M, N] = size(f);

% Given parameters
A = 200;
mu0 = 0.25;
nu0 = 0;

% Create coordinate grid
[x, y] = meshgrid(0:N-1, 0:M-1);

% Create periodic noise
eta = A * sin(2*pi*mu0*x + 2*pi*nu0*y);

% Add noise to image
g = f + eta;

% Clip values to valid image range [0, 255]
g = max(min(g, 255), 0);

% Display original and degraded image
figure; %[output:2a035d1f]

subplot(1,2,1); %[output:2a035d1f]
imshow(f, []); %[output:2a035d1f]
title('Original Image'); %[output:2a035d1f]

subplot(1,2,2); %[output:2a035d1f]
imshow(g, []); %[output:2a035d1f]
title('Degraded Image with Periodic Noise'); %[output:2a035d1f]


% Part (b)

% Fourier transform of degraded image
G = fft2(g);
G_shifted = fftshift(G);

% Frequency coordinate grid centered at zero
[u, v] = meshgrid(-floor(N/2):ceil(N/2)-1, ...
                  -floor(M/2):ceil(M/2)-1);

% Notch frequency locations
u0 = mu0 * N;
v0 = nu0 * M;

% Choose cutoff frequency
D0 = 10;

% Distance from positive notch center
D1 = sqrt((u - u0).^2 + (v - v0).^2);

% Distance from negative notch center
D2 = sqrt((u + u0).^2 + (v + v0).^2);

% Gaussian notch reject filter
H = (1 - exp(-(D1.^2) / (2*D0^2))) .* ...
    (1 - exp(-(D2.^2) / (2*D0^2)));

% Apply filter in frequency domain
Fhat_shifted = H .* G_shifted;

% Inverse Fourier transform
f_filtered = real(ifft2(ifftshift(Fhat_shifted)));

% Clip result to valid image range
f_filtered = max(min(f_filtered, 255), 0);

%% Display frequency spectrum, filter, and filtered image

figure; %[output:1a6433fb]

subplot(1,3,1); %[output:1a6433fb]
imshow(log(1 + abs(G_shifted)), []); %[output:1a6433fb]
title('Spectrum of Degraded Image'); %[output:1a6433fb]

subplot(1,3,2); %[output:1a6433fb]
imshow(H, []); %[output:1a6433fb]
title('Gaussian Notch Reject Filter'); %[output:1a6433fb]

subplot(1,3,3); %[output:1a6433fb]
imshow(f_filtered, []); %[output:1a6433fb]
title(['Filtered Image, D_0 = ', num2str(D0)]); %[output:1a6433fb]


